import React, { useState, useEffect } from "react";
import "./ViewTasks.css"; 
import Navbar from "../components/navbar"; 
import Footer from "../components/footer"; 
import StudentSidebar from "../components/StudentSidebar"; 
import axios from "axios";

const ViewTasks = () => {
  const [milestones, setMilestones] = useState([]);
  const [newMilestone, setNewMilestone] = useState("");
  const [newTask, setNewTask] = useState({
    title: "",
    creator: "",
    status: "Pending",
    completedBy: "",
    createdAt: "",
    deadline: "",
  });
  const [user, setUser] = useState(null); // Store current user

  // Fetch student data from localStorage
  useEffect(() => {
    const currentUser = JSON.parse(localStorage.getItem("users"));
    setUser(currentUser); // Set the user data from localStorage

    // Fetch milestones and tasks from the backend
    const fetchMilestones = async () => {
      try {
        const response = await axios.get("http://localhost:5000/api/milestone");
        setMilestones(response.data); // Set milestones fetched from backend
      } catch (error) {
        console.error("Error fetching milestones:", error);
      }
    };

    fetchMilestones();
  }, []); // Empty dependency array ensures this runs on component mount only

  // Function to add a new milestone
  const handleAddMilestone = async () => {
    if (!newMilestone.trim()) {
      alert("Please enter a milestone name.");
      return;
    }
    const milestoneData = {
      title: newMilestone,
      projectID: user ? user.id : "", // Assuming the projectID is linked to user
      dueDate: new Date(), // Set dueDate to current date for now, adjust as necessary
      status: "Pending", // Default status is "Pending"
    };

    try {
      const response = await axios.post("http://localhost:5000/api/milestone", milestoneData);
      setMilestones([...milestones, response.data]); // Add the newly created milestone to the list
      setNewMilestone(""); // Clear input field after adding
    } catch (error) {
      console.error("Error adding milestone:", error);
    }
  };

  // Function to add a new task under a specific milestone
  const handleAddTask = async (milestoneId) => {
    if (!newTask.title.trim() || !newTask.creator.trim()) {
      alert("Please fill in all task fields.");
      return;
    }

    // Prepare task data
    const taskData = {
      milestoneId: milestoneId,
      title: newTask.title,
      status: newTask.status,
      uploadedBy: user ? user.studentName : "", // Set creator to the current student name
    };

    try {
      // Send task data to the backend
      const response = await axios.post("http://localhost:5000/api/task", taskData);

      // Update the UI with the new task
      setMilestones((prevMilestones) =>
        prevMilestones.map((milestone) =>
          milestone._id === milestoneId
            ? {
                ...milestone,
                tasks: [...milestone.tasks, response.data], // Add the newly created task to the milestone
              }
            : milestone
        )
      );

      // Reset task fields
      setNewTask({ title: "", creator: "", status: "Pending", completedBy: "", createdAt: "", deadline: "" });
    } catch (error) {
      console.error("Error adding task:", error);
    }
  };

  // Function to update task status
  const handleUpdateTaskStatus = async (milestoneId, taskId, newStatus, studentName) => {
    try {
      // Update task status on the backend
      const updatedTask = await axios.put(`http://localhost:5000/api/task/${taskId}`, {
        status: newStatus,
        completedBy: studentName,
        completedAt: new Date().toLocaleString(),
      });

      // Update the task status in the UI
      setMilestones((prevMilestones) =>
        prevMilestones.map((milestone) =>
          milestone._id === milestoneId
            ? {
                ...milestone,
                tasks: milestone.tasks.map((task) =>
                  task._id === taskId ? { ...task, ...updatedTask.data } : task
                ),
              }
            : milestone
        )
      );
    } catch (error) {
      console.error("Error updating task status:", error);
    }
  };

  return (
    <div className="tasks-container">
      <Navbar />
      <div className="content-wrapper">
        <StudentSidebar />
        <div className="main-content">
          <h1 className="tasks-title">Manage Milestones and Tasks</h1>

          {/* Input Field for Adding a Milestone */}
          <div className="milestone-section">
            <input 
              type="text" 
              value={newMilestone} 
              onChange={(e) => setNewMilestone(e.target.value)} 
              placeholder="Add a new milestone" 
            />
            <button onClick={handleAddMilestone}>Add Milestone</button>
          </div>

          {/* List of Milestones with Tasks */}
          <div className="milestone-list">
            {/* Ensure milestones is always an array */}
            {milestones && milestones.length > 0 ? (
              milestones.map((milestone) => (
                <div key={milestone._id} className="milestone-item">
                  <h2>{milestone.title}</h2>
                  <p>Created on: {new Date(milestone.createdAt).toLocaleString()}</p>

                  {/* Input Fields for Adding a Task to the Milestone */}
                  <div className="task-section">
                    <input 
                      type="text" 
                      value={newTask.title} 
                      onChange={(e) => setNewTask({ ...newTask, title: e.target.value })} 
                      placeholder="Task title" 
                    />
                    <input 
                      type="text" 
                      value={newTask.creator} 
                      onChange={(e) => setNewTask({ ...newTask, creator: e.target.value })} 
                      placeholder="Created by" 
                    />
                    <button className="task-button" onClick={() => handleAddTask(milestone._id)}>Add Task</button>

                    {/* Table of Tasks Under the Milestone */}
                    <div className="tasks-table">
                      <table>
                        <thead>
                          <tr>
                            <th>Task</th>
                            <th>Creator</th>
                            <th>Status</th>
                            <th>Completed By</th>
                            <th>Created At</th>
                            <th>Actions</th>
                          </tr>
                        </thead>
                        <tbody>
                          {milestone.tasks && milestone.tasks.length > 0 ? (
                            milestone.tasks.map((task) => (
                              <tr key={task._id}>
                                <td>{task.title}</td>
                                <td>{task.uploadedBy}</td>
                                <td>{task.status}</td>
                                <td>{task.completedBy || "N/A"}</td>
                                <td>{new Date(task.createdAt).toLocaleString()}</td>
                                <td>
                                  <button 
                                    className="mark-completed-button" 
                                    onClick={() => handleUpdateTaskStatus(milestone._id, task._id, "Completed", user ? user.studentName : "")}
                                  >
                                    Mark as Completed
                                  </button>
                                </td>
                              </tr>
                            ))
                          ) : (
                            <tr><td colSpan="6">No tasks found.</td></tr>
                          )}
                        </tbody>
                      </table>
                    </div>
                  </div>
                </div>
              ))
            ) : (
              <p>No milestones available. Please add some milestones.</p>
            )}
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default ViewTasks;
